<template><div class="app-container ps-page"><h2>运行状态与受控作业</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><div class="ps-toolbar"><el-button :loading="loading" @click="refresh">刷新状态</el-button><el-button v-hasPermi="['paismart:operation:plan']" @click="planOpen=true">创建维护计划</el-button><el-button v-hasPermi="['paismart:conversation:audit']" @click="loadAudit">查看操作审计</el-button><el-button v-hasPermi="['paismart:operation:plan']" @click="callsOpen=true">模型与 OCR 核账</el-button></div><div class="ps-grid" v-if="status"><el-card v-for="component in status.components" :key="component.name" shadow="never"><strong>{{component.name}}</strong><p><el-tag :type="['UP','READY','HEALTHY'].includes(component.state)?'success':'warning'">{{component.state}}</el-tag></p><p class="ps-muted">{{component.reason||'未返回异常原因'}}</p><small v-if="component.latencyMs!==undefined">耗时 {{component.latencyMs}} ms</small></el-card></div><el-alert v-for="(item,i) in status?.configurationErrors||[]" :key="i" :title="item" type="warning" :closable="false" class="ps-section"/><el-card class="ps-section" shadow="never"><template #header>维护计划复核队列</template><el-alert v-if="plansError" :title="plansError" type="error" :closable="false"/><el-form inline><el-form-item label="计划状态"><el-select v-model="planQuery.state" clearable><el-option label="待批准" value="PENDING_APPROVAL"/><el-option label="已批准" value="APPROVED"/><el-option label="已受理执行" value="QUEUED"/><el-option label="正在执行" value="EXECUTING"/><el-option label="已完成" value="SUCCEEDED"/><el-option label="失败" value="FAILED"/></el-select></el-form-item><el-button @click="loadPlans(true)">查询计划</el-button></el-form><el-table :data="plans" v-loading="plansLoading"><el-table-column prop="type" label="维护类型" width="170"/><el-table-column prop="reason" label="业务原因" min-width="240"/><el-table-column prop="state" label="状态" width="170"/><el-table-column prop="createdBy" label="发起人" width="100"/><el-table-column prop="approvedBy" label="批准人" width="100"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="reviewPlan(row)">查看并复核</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="planQuery.pageNum" :page-size="planQuery.pageSize" :total="planTotal" layout="total,prev,pager,next" @current-change="loadPlans()"/></el-card><el-form inline><el-form-item label="作业状态"><el-select v-model="query.state" clearable><el-option v-for="s in ['QUEUED','RUNNING','RETRY','SUCCEEDED','FAILED','CANCELED']" :key="s" :label="stateLabel(s)" :value="s"/></el-select></el-form-item><el-button @click="load(true)">查询作业</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column prop="jobId" label="作业 ID" min-width="210" show-overflow-tooltip/><el-table-column prop="kind" label="类型" width="140"/><el-table-column label="状态" width="130"><template #default="{row}">{{stateLabel(row.state)}}</template></el-table-column><el-table-column prop="progress" label="进度" width="90"/><el-table-column prop="errorMessage" label="原因" min-width="220"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="view(row)">进度</el-button><el-button v-hasPermi="['paismart:operation:execute']" v-if="row.state==='FAILED'" link @click="act(row,'retry')">重试</el-button><el-button v-hasPermi="['paismart:operation:execute']" v-if="!terminal(row.state)" link type="warning" @click="act(row,'cancel')">取消</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load()"/><JobDialog v-model="jobOpen" :initial="job" administrative @done="load()"/><el-dialog v-model="planOpen" title="受控维护计划" width="720px"><el-alert title="先生成计划再审阅范围与版本。执行由服务端权限与批准范围裁决，不允许清空共享数据。" type="warning" :closable="false" class="ps-section"/><el-form label-width="100px"><el-form-item label="操作类型"><el-select v-model="kind"><el-option label="对象迁移计划" value="object-migrations"/><el-option label="过期对象清理计划" value="cleanup-plans"/><el-option label="初始数据导入计划" value="bootstrap-import"/></el-select></el-form-item><el-form-item v-if="kind!=='cleanup-plans'" label="实际对象清单" required><el-input v-model="manifestSource" type="textarea" :rows="9" placeholder="填写实际对象 JSON 数组，最多 1000 项"/><p class="ps-muted">{{manifestGuide}}</p></el-form-item><p v-else class="ps-muted">服务端按当前管理范围生成超过 30 天软删保留期的候选清单；批准前须复核具体文档、对象键、摘要与大小。</p><el-form-item label="业务原因" required><el-input v-model="reason" type="textarea" maxlength="1000"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-descriptions v-if="plan" :column="1" border><el-descriptions-item label="计划 ID">{{plan.id}}</el-descriptions-item><el-descriptions-item label="版本">{{plan.planVersion}}</el-descriptions-item><el-descriptions-item label="状态">{{stateLabel(plan.state)}}</el-descriptions-item></el-descriptions><h3 v-if="plan">计划清单</h3><pre v-if="plan" class="ps-pre manifest">{{JSON.stringify(plan.manifest,null,2)}}</pre><el-input v-model="planId" aria-label="待读取计划 ID" placeholder="粘贴计划 ID 以读取和复核"/><el-button @click="readPlan">读取已有计划</el-button><el-checkbox v-if="plan" v-model="confirmed">已核对范围、计划版本和恢复条件</el-checkbox><template #footer><el-button @click="planOpen=false">关闭</el-button><el-button :loading="saving" @click="createPlan">生成计划</el-button><el-button v-if="plan?.state==='PENDING_APPROVAL'" v-hasPermi="['paismart:operation:execute']" :disabled="!confirmed" :loading="saving" @click="approve">批准当前版本</el-button><el-button v-if="plan?.state==='APPROVED'" v-hasPermi="['paismart:operation:execute']" type="danger" :disabled="!confirmed||!plan.planVersion" :loading="saving" @click="execute">执行已核对计划</el-button></template></el-dialog><el-drawer v-model="auditOpen" title="知识库审计" size="min(1100px,95vw)"><el-tabs v-model="auditTab" @tab-change="loadAudit"><el-tab-pane label="操作审计" name="activities"/><el-tab-pane label="会话审计" name="conversations"/></el-tabs><el-table v-if="auditTab==='activities'" :data="activities"><el-table-column prop="createdAt" label="时间" min-width="180"/><el-table-column prop="userName" label="操作人" min-width="130"/><el-table-column prop="action" label="操作" min-width="140"/><el-table-column prop="target" label="目标" min-width="200"/><el-table-column prop="state" label="结果" width="100"/><el-table-column prop="reason" label="说明" min-width="220"/></el-table><template v-else><el-form inline><el-form-item label="用户 ID"><el-input v-model="auditQuery.userId"/></el-form-item><el-form-item label="会话标题"><el-input v-model="auditQuery.keyword"/></el-form-item><el-form-item label="日期范围"><el-date-picker v-model="auditDates" type="daterange" value-format="YYYY-MM-DD"/></el-form-item><el-button @click="searchAudit">查询</el-button><el-button @click="resetAudit">重置</el-button></el-form><el-table :data="auditedConversations"><el-table-column prop="userName" label="平台用户" min-width="160"/><el-table-column prop="title" label="会话" min-width="260"/><el-table-column prop="messageCount" label="消息数" width="90"/><el-table-column prop="updatedAt" label="更新时间" min-width="180"/><el-table-column label="查看" width="110"><template #default="{row}"><el-button link type="primary" @click="viewAudited(row)">查看消息</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="auditQuery.pageNum" :page-size="auditQuery.pageSize" :total="auditTotal" layout="total,prev,pager,next" @current-change="loadAudit"/></template></el-drawer><el-drawer v-model="auditMessageOpen" title="会话正文审计" size="min(850px,95vw)"><el-alert v-if="auditError" :title="auditError" type="error" :closable="false"/><ChatMessage v-for="item in auditedMessages" :key="item.id" :message="item" streaming @reference="openReference"/><el-pagination v-model:current-page="auditMessagePage" :page-size="50" :total="auditMessageTotal" layout="total,prev,pager,next" @current-change="loadAuditedMessages"/></el-drawer><ReferencePreview v-model="referenceOpen" :reference="selectedReference"/><CallReconciliation v-model="callsOpen"/></div></template>
<script setup lang="ts">
import { computed,onMounted,ref,shallowRef } from 'vue'
import { listPlans,auditConversations,auditMessages,approvePlan,getPlan,executePlan,jobAction,listActivities,listJobs,operationStatus,planOperation } from '@/api/paismart/operations'
import type { Activity,Job,Message,OperationPlan,OperationStatus,Reference } from '@/types/paismart'
import JobDialog from '../../components/JobDialog.vue'
import ChatMessage from '../../chat/components/ChatMessage.vue'
import { errorText,stateLabel,terminal,usePage } from '../../composables/usePage'
import ReferencePreview from '../../chat/components/ReferencePreview.vue'
import CallReconciliation from './CallReconciliation.vue'
import {operationManifest} from '../../composables/operationManifest'
import '../../common.css'
const {rows:plans,total:planTotal,query:planQuery,loading:plansLoading,error:plansError,load:loadPlans}=usePage(listPlans,{state:'PENDING_APPROVAL'});
const {rows,total,query,loading,error,load}=usePage(listJobs),status=shallowRef<OperationStatus>(),job=shallowRef<Job>(),plan=shallowRef<OperationPlan>(),activities=shallowRef<Activity[]>([]),pageError=ref(''),formError=ref(''),jobOpen=ref(false),planOpen=ref(false),auditOpen=ref(false),saving=ref(false),kind=ref('cleanup-plans'),manifestSource=ref(''),reason=ref(''),confirmed=ref(false),planId=ref(''),auditTab=ref('activities'),auditQuery=ref({pageNum:1,pageSize:20,userId:'',keyword:'',startTime:'',endTime:''}),auditTotal=ref(0),auditedConversations=shallowRef<Record<string,unknown>[]>([]),auditedMessages=shallowRef<Message[]>([]),auditMessageOpen=ref(false),auditMessagePage=ref(1),auditMessageTotal=ref(0),auditConversationId=ref(''),auditError=ref('')
const callsOpen=ref(false),referenceOpen=ref(false),selectedReference=shallowRef<Reference>(),auditDates=ref<string[]>([])
const manifestGuide=computed(()=>kind.value==='object-migrations'?'每项：id、sourceKey、targetKey、sha256、byteSize；源对象保留，目标键须属于 paismart/documents/{id}/。旧源迁入以 legacySourceKey 代替 sourceKey；旧分片还需 uploadId/chunkNo（0基），目标为 paismart/uploads/{uploadId}/{chunkNo}。':'每项：sourceKey、filename、sha256、byteSize、spaceId（可空）、visibility；可选 ownerId、logicalKey、repair（布尔值，显式修复）。同逻辑知识新版会软删旧版并保留源。导入源须属于 paismart/imports/，无需本机或服务器路径。')
function openReference(reference:Reference){selectedReference.value=reference;referenceOpen.value=true}
function searchAudit(){auditQuery.value.pageNum=1;auditQuery.value.startTime=auditDates.value?.[0]??'';auditQuery.value.endTime=auditDates.value?.[1]??'';void loadAudit()}
function resetAudit(){auditDates.value=[];auditQuery.value.userId='';auditQuery.value.keyword='';searchAudit()}
async function refresh(){pageError.value='';void load();void loadPlans();try{status.value=(await operationStatus()).data}catch(e){pageError.value=errorText(e)}}
function view(row:Job){job.value=row;jobOpen.value=true}
async function act(row:Job,action:'retry'|'cancel'){pageError.value='';try{job.value=(await jobAction(row.jobId,action)).data;jobOpen.value=true;await load()}catch(e){pageError.value=errorText(e)}}
async function createPlan(){formError.value='';if(!reason.value.trim()){formError.value='请填写业务原因';return}saving.value=true;confirmed.value=false;try{const manifest=operationManifest(kind.value,manifestSource.value);plan.value=(await planOperation(kind.value,{...manifest,reason:reason.value.trim()})).data;await loadPlans()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function reviewPlan(row:OperationPlan){planId.value=String(row.id);planOpen.value=true;await readPlan()}
async function readPlan(){if(!planId.value.trim())return;formError.value='';confirmed.value=false;try{plan.value=(await getPlan(planId.value.trim())).data}catch(e){formError.value=errorText(e)}}
async function approve(){if(!plan.value||!confirmed.value)return;saving.value=true;formError.value='';try{plan.value=(await approvePlan(plan.value.id,plan.value.planVersion)).data;confirmed.value=false;await loadPlans()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function execute(){if(!plan.value?.planVersion||!confirmed.value)return;saving.value=true;formError.value='';try{job.value=(await executePlan(plan.value.id,plan.value.planVersion)).data;jobOpen.value=true;planOpen.value=false;await load();await loadPlans()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function loadAudit(){pageError.value='';try{if(auditTab.value==='conversations'){const response=await auditConversations(auditQuery.value);auditedConversations.value=response.rows;auditTotal.value=response.total}else activities.value=(await listActivities({pageNum:1,pageSize:100})).rows;auditOpen.value=true}catch(e){pageError.value=errorText(e)}}
async function viewAudited(row:Record<string,unknown>){auditConversationId.value=String(row.id);auditMessagePage.value=1;auditMessageOpen.value=true;await loadAuditedMessages()}
async function loadAuditedMessages(){auditError.value='';try{const response=await auditMessages(auditConversationId.value,{pageNum:auditMessagePage.value,pageSize:50});auditedMessages.value=response.rows;auditMessageTotal.value=response.total}catch(e){auditError.value=errorText(e)}}
onMounted(()=>void refresh())
</script>

<style scoped>.manifest{max-height:340px;overflow:auto;border:1px solid var(--el-border-color);padding:12px}</style>
